"file":"lib/capture-meadow-layout.ts","sha256":"dc1f28d249dfceaa7397d3f1ff03e09bed7fd24a1ec1a09508559c45d81db6cd","lines":[{"first":52,"last":74,"code":"/** True where a grass root and its optional horizontal reach (metres) fit. */
export function isMeadowPoint(x: number, z: number, margin = 0): boolean {
  if (!Number.isFinite(x) || !Number.isFinite(z) || !Number.isFinite(margin) || margin < 0) return false;
  if (x <= meadowBounds.minX + margin || x >= meadowBounds.maxX - margin ||
      z <= meadowBounds.minZ + margin || z >= meadowBounds.maxZ - margin) return false;

  // Support lines in the decoded mesh. Everything on the camera side of the
  // near walk is excluded; planting on that side is outside the pictured lawn.
  const near = -.64991375 * x + .76000797 * z;
  if (near >= 3.93095 - verge - margin) return false;
  const cross = -.34559091 * x + .93838527 * z;
  if (cross >= -12.41253 - verge - margin && cross <= -10.70670 + verge + margin) return false;

  for (const [cx, cz, radius] of bases) {
    const dx = x - cx, dz = z - cz, clearance = radius + verge + margin;
    if (dx * dx + dz * dz <= clearance * clearance) return false;
  }
  // Both photo-only obstacles are confined to this small foreground region.
  if (x >= -1.5 - margin && x <= 4.1 + margin && z >= 2.3 - margin && z <= 4.5 + margin) {
    for (const polygon of obstacles) if (nearPolygon(x, z, polygon, .08 + margin)) return false;
  }
  return true;
}"}]},"actualStageBHandoffs":[{"taskId":"lawn-r4-b-contact","responseSha256":"35885ca95c4d45ec790ba609d29797d0837a94f915df205922e9b7ebbd3905f3","responseText":"{
  "name": "eligible_pair",
  "expression": "1 if left_turf == 1 and right_turf == 1 and left_blocked == 0 and right_blocked == 0 else 0",
  "implementation": "供第二轮固定输入的像素缓冲试验接入：对已确认同材质的边界像素对传入四个 0/1 标记；仅返回 1 时应用修正，返回 0 时两侧均保留原值。缺失元数据由上游拒绝，不默认放行。",
  "limits": "孤立草坪图集内的放行不代表场景地面可放行；场景仍须提供可靠的草坪分类及铺装、保护对象遮罩。提供的证据报告了两张实际嵌入纹理的 CPU A/B 试验，仅支持重复边界指标改善，不能证明整片草坪可见接缝已解决。本次未读取纹理或执行第二轮试验，既有测试数量不构成本函数的实测结果。"
}"},{"taskId":"lawn-r4-b-scale","responseSha256":"7606a7b691c165b1f40e4a1f89f301a6d25c538b11ced2c8dcca455a4639e91b","responseText":"{
  "name": "band_detail_change",
  "expression": "0 if floor <= 0 else (new_gradient - old_gradient) / max(old_gradient, floor)",
  "implementation": "第二轮像素缓冲试验中，对修复前后相同像素区域，在线性亮度下计算方向一致的平均绝对梯度，分别传入 old_gradient、new_gradient；floor 使用同量纲的固定正数。左、右、上、下各取单侧边带并分别报告，不将跨重复边界的跳变混入带内梯度，角区采用一致的排除规则。负值表示细节衰减，正值表示放大。固定12纹素边带在512与2048分辨率下分别占边长约2.344%与0.586%，因此需另做相同归一化带宽的对照；相机LOD测试涉及投影、过滤与距离切换，不能由静态纹理带宽测试替代。",
  "limits": "假定梯度有限且非负、floor有限；floor<=0返回零，不额外处理负梯度、NaN或无穷值。旧梯度低于floor时，结果是以floor稳定化的相对变化，并非严格百分比损失。所给证据报告了两张实际嵌入纹理的首轮CPU试验，并非相机渲染；若floor不高于各旧梯度，已给聚合梯度分别约增加0.213%和1.380%，不能据此断言每侧均无细节损失。此处未读取像素或执行第二轮试验，未独立核验这些结果，也不声称整片草坪的可见接缝已解决。"
}"}],"stageBUseAndScope":"B was tested on repeated borders of the two old textures. The R4 candidate instead integrates stage A feather/tone on a single world material, and detail_mix in viewer LOD. This review is of the entire rendered R4.","requiredChecks":{"protectedMax01":{"actual":0.0,"operator":"eq","limit":0,"unit":"sRGB code values","whatItTests":"tested bare-render object ROI means are pixel-identical"},"protectedMax13":{"actual":0.0,"operator":"eq","limit":0,"unit":"sRGB code values","whatItTests":"tested bare-render object ROI means are pixel-identical"},"testedMaxWindReach":{"actual":0.0882863734,"operator":"lt","limit":0.108,"unit":"metres","whatItTests":"tested +/-12m/s leaf excursion remains inside reserved exclusion margin"}},"imageInputs":{"format":"2 rows × 3 columns. For each registered camera: real campus grass crop, original simulator R3, current simulator R4. Crops may include physical structures. Do not infer measured species, frame rate, metric scale or unobserved boundaries.","jpegSha256":"102e76af9bbe256e3b5e07c40057c91b5426abf6f2f16800c785a0a0bfe09ac9","sources":[{"camera":"01","source":"PHOTO","sourceSha256":"7b31bab3cf0b5873d858b577dd3073a0785d7fe4dea534e9049a259051890ee6","sourcePixelXYXY":[50,524,590,720],"layer":"registered photo"},{"camera":"01","source":"R3","sourceSha256":"a1491b2db62d073d7eaaefa0101109d909b13a798ee7b57a07e02b4856fc3c4f","sourcePixelXYXY":[50,524,590,720],"layer":"bare"},{"camera":"01","source":"R4","sourceSha256":"85458b23ee6a5a5be47feca3cf4c285ff7e9b082aff9f1dc160a012f829d083a","sourcePixelXYXY":[50,524,590,720],"layer":"bare"},{"camera":"13","source":"PHOTO","sourceSha256":"1501fd6de67567552dd1cca488320fa1ccc443813990f905ffdda39ed6e5f6be","sourcePixelXYXY":[125,485,760,687],"layer":"registered photo"},{"camera":"13","source":"R3","sourceSha256":"d640d6a45f385a1bf6a4869b0247b44819652d186caf5c2b326cf1512a308611","sourcePixelXYXY":[125,485,760,687],"layer":"bare"},{"camera":"13","source":"R4","sourceSha256":"67ecf7c183521f538cc9547ea2fa9a5c53b0c1d91694bd37edc69e77ee3039ab","sourcePixelXYXY":[125,485,760,687],"layer":"bare"}]}}

