{"taskId":"lawn-r4-c-qa","role":"qa","purpose":"担任独立整体验收人。从固定视图图像和不同比例的实测结果作可核对的上线判定。区分材质接缝、受保护对象、明暗和渲染性能；指出最不确定、可能推翻当前结论的一项，并给下次最有价值的具体验证。不要把平均值降低描述为每个局部都接近实拍。","currentCandidateSha256":"959985d05424fcaa205f4819780255f75b7f1e5ad6e7a8f97d97ff7b7bf3533d","oldSceneSha256":"18f8d13e88ca8d764a7b881f04a798efdf7b20ad4db5135ec1c6a8b78b226005","frozenAcceptanceProtocolSha256":"1e776637e97d36c15344e1b2a38d264e1ff20404af7691c509775385d92cedc7","fixedCameraPixels":[1024,768],"measuredEvidence":{"shadeSun01":{"R3":{"bare":1.02004702,"blades":1.00731974,"photo":0.07005292},"R4":{"bare":0.15764955,"blades":0.15332145,"photo":0.07005292}},"frozenNorth01":{"R3":{"bare":{"count":10,"meanExcess":0.0036660245439692845,"p90Excess":0.006680815963448296},"blades":{"count":10,"meanExcess":0.013105509004644762,"p90Excess":0.04865667406190732},"photo":{"count":10,"meanExcess":0.013650675309028335,"p90Excess":0.03357696066467254}},"R4":{"bare":{"count":10,"meanExcess":0.001269177325298021,"p90Excess":0.0028829820321905476},"blades":{"count":10,"meanExcess":0.006223723687860935,"p90Excess":0.01461129353838835},"photo":{"count":10,"meanExcess":0.013650675309028335,"p90Excess":0.03357696066467254}}},"numberOfAcceptedNeighborhoods01":{"north":10,"east":0,"west":0},"runtime01":{"old":{"seed":1942029223,"fieldTufts":384606,"tufts":14654,"blades":105226,"drawCalls":8,"nearBlades":0,"middleBlades":22605,"farBlades":82621},"r4":{"seed":1942029223,"fieldTufts":384606,"tufts":14643,"blades":105028,"drawCalls":8,"nearBlades":0,"middleBlades":22386,"farBlades":82642}},"protected01":{"foreground-trunk":{"roi":[574,572,582,601],"meanAbsRGB255":0.0,"count":232},"lamp-pole":{"roi":[160,546,165,598],"meanAbsRGB255":0.0,"count":260},"green-cover":{"roi":[526,662,553,668],"meanAbsRGB255":0.0,"count":162},"paving":{"roi":[221,698,288,714],"meanAbsRGB255":0.0,"count":1072}},"shadeSun13":{"R3":{"bare":1.18674565,"blades":1.30928502,"photo":0.05524635},"R4":{"bare":0.18759035,"blades":0.18864561,"photo":0.05524635}},"frozenNorth13":{"R3":{"bare":{"count":10,"meanExcess":0.002558314403063386,"p90Excess":0.00905951686957815},"blades":{"count":10,"meanExcess":0.01994510611886511,"p90Excess":0.0396424632330188},"photo":{"count":10,"meanExcess":0.003794247368719328,"p90Excess":0.012845546518281781}},"R4":{"bare":{"count":10,"meanExcess":0.00047327445958305904,"p90Excess":0.0015451336724899734},"blades":{"count":10,"meanExcess":0.006918853511637002,"p90Excess":0.015237536597234203},"photo":{"count":10,"meanExcess":0.003794247368719328,"p90Excess":0.012845546518281781}}},"numberOfAcceptedNeighborhoods13":{"north":10,"east":0,"west":0},"runtime13":{"old":{"seed":1942029223,"fieldTufts":384606,"tufts":15122,"blades":110720,"drawCalls":8,"nearBlades":0,"middleBlades":28264,"farBlades":82456},"r4":{"seed":1942029223,"fieldTufts":384606,"tufts":15126,"blades":110692,"drawCalls":8,"nearBlades":0,"middleBlades":28244,"farBlades":82448}},"protected13":{"foreground-trunk":{"roi":[666,504,679,533],"meanAbsRGB255":0.0,"count":377},"lamp-pole":{"roi":[157,522,163,575],"meanAbsRGB255":0.0,"count":318},"green-cover":{"roi":[706,613,740,623],"meanAbsRGB255":0.0,"count":340},"paving":{"roi":[225,668,286,680],"meanAbsRGB255":0.0,"count":732}},"browserExceptionCount":0,"mobile":{"viewport":390,"page":390,"canvas":352.90625,"blades":"105,028"},"sameProjection":true},"sourceExcerpt":{"file":"lib/capture-meadow.test.mjs","sha256":"a579edd112a7532023ede291f6c3074c86360087539636e69fd87e6a4e231d60","lines":[{"first":58,"last":100,"code":"// of the tuft generator's hash, scaling and rotation transforms.
test('fine-detail population tapers in metres without a jump in slope at either end', () => {
  for(const [near,far] of [[3.7,5.3],[10.5,14.5]]){
    let prev=1;
    for(let i=0;i<=100;i++){
      const distance=near+(far-near)*i/100,w=meadowDetailMix(distance,near,far);
      assert.ok(w>=0 && w<=prev);prev=w;
    }
    assert.equal(meadowDetailMix(near-.2,near,far),1);
    assert.equal(meadowDetailMix(far+.2,near,far),0);
    assert.ok(1-meadowDetailMix(near+.001,near,far)<.00001);
    assert.ok(meadowDetailMix(far-.001,near,far)<.00001);
  }
  assert.equal(meadowDetailMix(4,5,5),0);
});

