ving continuity across all material and mesh boundaries."},"worldNorthExample":{"x":-8,"z":-34,"sameScaleStripSpacingM":1.2,"01centres":[[409.23,519.83],[405.17,520.9]],"13centres":[[253.91,443.8],[251.36,445.1]]}},"sourceExcerpt":{"file":"infra/reconstruction/patch_turf_glb.mjs","sha256":"fec45aa1e2499fb2576dd6438599617a296cd763587b10d2b7ad6ca153253a3c","lines":[{"first":63,"last":118,"code":"}
