type Scenario = 'preaborted' | 'abort_after_commit' | 'abort_during_read' | 'retry_short_middle' | 'out_of_order' | 'fresh_after_abort';
type Case = { name: string; scenario: Scenario; outcome: 'abort' | 'complete' };
type Gen = 'old' | 'new';
type Done = { ok: true; value: ArrayBuffer } | { ok: false; error: unknown };
type Job = { done?: Done };
const N = 5242917, C = 2097152, T = N - 2 * C, PREFIX = 293625;
