  { name: 'abort_after_commit', scenario: 'abort_after_commit', outcome: 'abort' },
  { name: 'abort_during_partial_read', scenario: 'abort_during_read', outcome: 'abort' },
  { name: 'retry_short_middle', scenario: 'retry_short_middle', outcome: 'complete' },
  { name: 'independent_out_of_order', scenario: 'out_of_order', outcome: 'complete' },
  { name: 'fresh_after_abort', scenario: 'fresh_after_abort', outcome: 'abort' },
  { name: 'abort_in_progress_callback', scenario: 'abort_after_commit', outcome: 'abort' }
];
function check(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function deferred<A>() {
  let resolve!: (value: A) => void;
  const promise = new Promise<A>(r => { resolve = r; });
