async function runCase(tc: Case): Promise<void> {
  const controllers = { old: new AbortController(), new: new AbortController() };
  const data = {} as Record<Gen, Uint8Array>;
  for (const g of ['old', 'new'] as const) {
    const seed = g === 'old' ? 17 : 113;
    data[g] = Uint8Array.from({ length: N }, (_, i) => (i * 31 + (i >>> 11) + seed) & 255);
  }
  const progress: Record<Gen, number[]> = { old: [], new: [] };
  const requests: { gen: Gen; start: number; attempt: number }[] = [];
  const attempts = new Map<string, number>();
  const pending = new Map<string, { gen: Gen; start: number; gate: ReturnType<typeof deferred<Response>> }>();
  const resume = deferred<void>();
  let prefixConsumed = false;
  let cut: number | undefined;
  let requestCut: number | undefined;
  const jobs: Job[] = [];
  const previousFetch = globalThis.fetch;
  const key = (g: Gen, start: number, attempt = 1) => `${g}:${start}:${attempt}`;
  const oldRequests = () => requests.filter(r => r.gen === 'old').length;

  function abortOld() {
    check(cut === undefined, '旧代只取消一次');
    cut = progress.old.length;
    requestCut = oldRequests();
    controllers.old.abort();
  }
  function checkFrozen() {
    check(cut !== undefined && progress.old.length === cut, '取消后旧代仍报告进度');
    check(oldRequests() === requestCut, '取消后旧代仍发起请求或重试');
  }
  function response(g: Gen, start: number, body?: BodyInit): Response {
    const end = Math.min(start + C, N) - 1;
    return new Response(body === undefined ? data[g].slice(start, end + 1) : body, {
      status: 206,
      headers: {
        'Content-Range': `bytes ${start}-${end}/${N}`,
        'Content-Length': String(end + 1 - start)
      }
    });
  }
  function release(g: Gen, start: number, attempt = 1) {
    const k = key(g, start, attempt);
    const held = pending.get(k);
    check(held, '没有对应的待交付请求: ' + k);
    pending.delete(k);
    held.gate.resolve(response(g, start));
  }
  function releaseOld() {
    resume.resolve();
    for (const held of [...pending.values()]) {
      if (held.gen === 'old') {
        for (const [k, value] of pending) if (value === held) pending.delete(k);
        held.gate.resolve(response(held.gen, held.start));
      }
    }
  }
  function trace(g: Gen, expected?: number[]) {
    const values = progress[g];
    let last = 0;
    const commits: number[] = [];
    for (const fraction of values) {
      check(Number.isFinite(fraction) && fraction >= 0 && fraction <= 1, '进度必须在 [0,1]');
      check(fraction >= last, '同代进度倒退');
      last = fraction;
      const bytes = Math.round(fraction * N);
      check(Math.abs(fraction * N - bytes) < 0.000001, '进度不是完整字节计数');
      if (bytes !== 0 && commits[commits.length - 1] !== bytes) commits.push(bytes);
    }
    if (expected) check(JSON.stringify(commits) === JSON.stringify(expected),
      `提交序列错误: ${g}: ${JSON.stringify(commits)}，期望 ${JSON.stringify(expected)}`);
  }
  function start(g: Gen): Job {
    const job: Job = {};
    jobs.push(job);
    Promise.resolve().then(() => readCaptureAsset(
      `https://offline.invalid/asset?generation=${g}`,
      controllers[g].signal,
      fraction => {
        progress[g].push(fraction);
        if (g === 'old' && tc.name === 'abort_in_progress_callback' && cut === undefined) {
          check(Math.round(fraction * N) === C, '诊断取消点不是首段提交');
          abortOld();
        }
      }
