    requests.push({ gen: g, start: startByte, attempt });
    const shortMiddle = g === 'old' && tc.scenario === 'retry_short_middle' && startByte === C;
    check(attempt <= (shortMiddle ? 2 : 1), '超出有界重试次数');
    // 故意不因 signal 自动拒绝，模拟取消时已经排队的响应或读取完成。
    if (startByte === 0 || tc.scenario === 'preaborted' || tc.name === 'abort_in_progress_callback') {
      return response(g, startByte);
    }
    if (g === 'new' && tc.scenario !== 'fresh_after_abort') return response(g, startByte);
    if (shortMiddle && attempt === 1) return response(g, C, data[g].slice(C, C + PREFIX));
    if (g === 'old' && tc.scenario === 'abort_during_read' && startByte === C) {
      let phase = 0;
      const stream = new ReadableStream<Uint8Array>({
        pull(controller) {
          if (phase++ === 0) {
            controller.enqueue(data.old.slice(C, C + PREFIX));
            return;
          }
          // highWaterMark=0：再次 pull 表示前缀已被消费者读取，而非仅入队。
          prefixConsumed = true;
          return resume.promise.then(() => {
            controller.enqueue(data.old.slice(C + PREFIX, 2 * C));
            controller.close();
