      release('old', 2 * C);
      await completed(old, 'old');
      trace('old', [C, 2 * C, N]);
      check(attempts.get(`old:${C}`) === 2, '中段没有恰好重试一次');
    } else {
      await until(() => pending.has(key('old', C)) && pending.has(key('old', 2 * C)), '首段提交且其余两段挂起');
