    trace(g);
    check(progress[g].length > 0 && progress[g][progress[g].length - 1] === 1, '完成时进度没有到 1');
  }

  globalThis.fetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    const url = new URL(typeof input === 'string' ? input : input instanceof URL ? input.href : input.url);
    check(url.origin === 'https://offline.invalid' && url.pathname === '/asset', '禁止访问非模拟地址');
    const generation = url.searchParams.get('generation');
    check(generation === 'old' || generation === 'new', '缺少代际标识');
    const g: Gen = generation;
    check(init?.signal === controllers[g].signal, '请求使用了错误代的信号');
    const match = /^bytes=(\d+)-(\d+)$/.exec(new Headers(init?.headers).get('Range') ?? '');
    check(match, '缺少合法 Range');
    const startByte = Number(match[1]);
    check([0, C, 2 * C].includes(startByte), '不允许的范围起点');
    check(Number(match[2]) === Math.min(startByte + C, N) - 1, '范围终点错误');
    check(url.searchParams.get('part') === String(startByte), 'part 与 Range 不一致');
    const countKey = `${g}:${startByte}`;
    const attempt = (attempts.get(countKey) ?? 0) + 1;
    attempts.set(countKey, attempt);
    requests.push({ gen: g, start: startByte, attempt });
    const shortMiddle = g === 'old' && tc.scenario === 'retry_short_middle' && startByte === C;
    check(attempt <= (shortMiddle ? 2 : 1), '超出有界重试次数');
    // 故意不因 signal 自动拒绝，模拟取消时已经排队的响应或读取完成。
    if (startByte === 0 || tc.scenario === 'preaborted' || tc.name === 'abort_in_progress_callback') {
      return response(g, startByte);
    }
    if (g === 'new' && tc.scenario !== 'fresh_after_abort') return response(g, startByte);
    if (shortMiddle && attempt === 1) return response(g, C, data[g].slice(C, C + PREFIX));
    if (g === 'old' && tc.scenario === 'abort_during_read' && startByte === C) {
      let phase = 0;
      const stream = new ReadableStream<Uint8Array>({
        pull(controller) {
          if (phase++ === 0) {
            controller.enqueue(data.old.slice(C, C + PREFIX));
            return;
          }
          // highWaterMark=0：再次 pull 表示前缀已被消费者读取，而非仅入队。
          prefixConsumed = true;
          return resume.promise.then(() => {
            controller.enqueue(data.old.slice(C + PREFIX, 2 * C));
            controller.close();
          });
        }
      }, { highWaterMark: 0 });
      return response(g, C, stream);
    }
    const gate = deferred<Response>();
    pending.set(key(g, startByte, attempt), { gen: g, start: startByte, gate });
    return gate.promise;
  };

  try {
    if (tc.scenario === 'preaborted') abortOld();
    const old = start('old');
    let fresh: Job | undefined;

    if (tc.scenario === 'preaborted') {
      await aborted(old);
      check(oldRequests() === 0 && progress.old.length === 0, '预取消不得调用 fetch 或进度');
    } else if (tc.name === 'abort_in_progress_callback') {
      await aborted(old);
      check(oldRequests() === 1, '进度回调内取消后仍调度其他范围');
    } else if (tc.scenario === 'abort_during_read') {
      await until(() => prefixConsumed && pending.has(key('old', 2 * C)), '中段前缀已消费');
      trace('old', [C]);
      abortOld();
      releaseOld();
      await aborted(old);
    } else if (tc.scenario === 'retry_short_middle') {
      await until(() => pending.has(key('old', C, 2)) && pending.has(key('old', 2 * C)), '短中段触发第二次请求');
      trace('old', [C]);
      release('old', C, 2);
      await until(() => progress.old.some(p => Math.round(p * N) === 2 * C), '重试中段提交');
      trace('old', [C, 2 * C]);
      release('old', 2 * C);
      await completed(old, 'old');
      trace('old', [C, 2 * C, N]);
      check(attempts.get(`old:${C}`) === 2, '中段没有恰好重试一次');
    } else {
      await until(() => pending.has(key('old', C)) && pending.has(key('old', 2 * C)), '首段提交且其余两段挂起');
      trace('old', [C]);
      if (tc.scenario === 'out_of_order') {
        release('old', 2 * C);
        await until(() => progress.old.some(p => Math.round(p * N) === C + T), '尾段先独立提交');
        trace('old', [C, C + T]);
        release('old', C);
        await completed(old, 'old');
        trace('old', [C, C + T, N]);
      } else {
        abortOld();
        if (tc.scenario === 'fresh_after_abort') {
          // 新用户动作发生在旧请求尚未交付时，且从不取消新代。
          fresh = start('new');
          await until(() => pending.has(key('new', C)) && pending.has(key('new', 2 * C)), '新代独立启动');
          trace('new', [C]);
        }
        releaseOld();
        await aborted(old);
        if (fresh) {
          trace('new', [C]);
          checkFrozen();
          release('new', 2 * C);
          await until(() => progress.new.some(p => Math.round(p * N) === C + T), '新代尾段提交');
          release('new', C);
          await completed(fresh, 'new');
          trace('new', [C, C + T, N]);
        }
      }
    }
    // 每例实际验证一次独立新调用，而不只声明它可以重试。
    if (!fresh) {
      fresh = start('new');
      await completed(fresh, 'new');
    }
    check(!controllers.new.signal.aborted, '新用户动作被错误取消');
    if (tc.outcome === 'abort') checkFrozen();
    const expectedOldRequests = tc.scenario === 'preaborted' ? 0
      : tc.name === 'abort_in_progress_callback' ? 1
      : tc.scenario === 'retry_short_middle' ? 4 : 3;
    check(oldRequests() === expectedOldRequests, '旧代请求总数错误');
    check(requests.filter(r => r.gen === 'new').length === 3, '新代应独立请求三段');
  } finally {
    // 即使断言失败也释放本地门闩，防止把悬挂读取带到下一例。
    resume.resolve();
    for (const held of pending.values()) held.gate.resolve(response(held.gen, held.start));
    pending.clear();
    for (let i = 0; i < 2048 && jobs.some(j => j.done === undefined); i++) await Promise.resolve();
    globalThis.fetch = previousFetch;
  }
}

export async function runRegression(): Promise<string[]> {
  const passed: string[] = [];
  const failures: Error[] = [];
  for (const tc of cases) {
    try {
      await runCase(tc);
      passed.push(tc.name);
    } catch (error) {
      failures.push(new Error(`${tc.name}: ${error instanceof Error ? error.message : String(error)}`));
    }
  }
  if (failures.length) throw new AggregateError(failures, '取消、重试与进度离线回归失败');
  return passed;
}

