建议将以下纯函数用于首片、后续分片及完整回退的统一决策；不执行任何 fetch。将本 JSON 的 fixtures 作为 runRangeFixtures 的参数即可直接进行本地判定。所有响应须在正文成功读取后再提交数据；accept_part 仅写入返回的 offset，accept_whole 必须作为偏移零的完整实体返回，不能写入原请求的非零偏移。完整回退完成后还应停止或忽略未完成的分片工作，避免混入旧分片。

type Expected = 'accept_part' | 'accept_whole' | 'discard_response';
export interface RangeFixture {
  name: string;
  status: number;
  askedStart: number;
  askedEnd: number;
  rangeStart: number;
  rangeEnd: number;
  rangeTotal: number;
  bodyBytes: number;
  assetBytes: number;
  expected: Expected;
}
export type RangeDecision =
  | { kind: 'discard_response' }
  | { kind: 'accept_part'; offset: number; length: number }
  | { kind: 'accept_whole'; offset: 0; length: number };
export function validateRange(f: Omit<RangeFixture, 'name' | 'expected'>): RangeDecision {
  const discard: RangeDecision = { kind: 'discard_response' };
  if (![f.status, f.askedStart, f.askedEnd, f.assetBytes, f.bodyBytes].every(Number.isSafeInteger)) return discard;
  if (f.assetBytes <= 0 || f.bodyBytes < 0 || f.askedStart < 0 || f.askedEnd < f.askedStart || f.askedEnd >= f.assetBytes) return discard;
  if (f.status === 200) {
    return f.bodyBytes === f.assetBytes
      ? { kind: 'accept_whole', offset: 0, length: f.assetBytes }
      : discard;
  }
  if (f.status !== 206) return discard;
  if (f.rangeStart !== f.askedStart || f.rangeEnd !== f.askedEnd || f.rangeTotal !== f.assetBytes) return discard;
  if (f.bodyBytes !== f.askedEnd - f.askedStart + 1) return discard;
  return { kind: 'accept_part', offset: f.askedStart, length: f.bodyBytes };
}
export function runRangeFixtures(fixtures: readonly RangeFixture[]): void {
  for (const f of fixtures) {
    const d = validateRange(f);
    if (d.kind !== f.expected) throw new Error(f.name + ': expected ' + f.expected + ', got ' + d.kind);
    if (d.kind === 'accept_whole' && (d.offset !== 0 || d.length !== f.assetBytes)) throw new Error(f.name + ': invalid whole placement');
    if (d.kind === 'accept_part' && (d.offset !== f.askedStart || d.length !== f.askedEnd - f.askedStart + 1)) throw new Error(f.name + ': invalid part placement');
  }
}

