  "evidenceLimits": "所给失败记录显示：发布 49f26c3 的 offset=16777216 条目报告 HTTP 206，但 encodedBodyBytes 只有 293625，并伴随 net::ERR_HTTP2_PROTOCOL_ERROR 和用户可见加载失败。这些是响应/浏览器记录，不能仅凭它们定位服务器、代理、浏览器或网络链路责任，更不能归因到某个账号。恢复记录报告剩余 1803527 字节，二者相加为 2097152，并记载查看器在解析前校验了完整分段；这支持“206 不保证本次读取完整”的回归方向，但不能证明应用自身实施了重试，也不能把 encodedBodyBytes 普遍等同于应用已提交字节。独立首试提供了完整范围响应记录和成功页面指标，说明故障并非每次必现。两次页面的选择编号、气流与草叶数量并不完全相同，不能据此作同视角视觉等价结论；本输入没有实际渲染图片可供重新检视。既有草边界验收结论也不证明传输恢复正确。提供的 GLB 和回执摘要在这里仅作为标识，未重新验证。缩小夹具使用合成字节，不是原 GLB，不应与原 GLB SHA256 比较，也不验证 GLB 解析、摄像机、草叶渲染或真实 HTTP/2 恢复。",
  "integration": {
    "file": "app/readCaptureAsset.range-recovery.test.ts",
    "operation": "// 拟新增的离线 TypeScript 诊断文件；从同目录导入被测实现。
// 本地 TS 测试运行器调用 runFixtures(本响应.fixtures)，再调用 assertPassing(结果)。
// 全程替换 fetch，不调用保存的原 fetch；禁止与其他修改全局 fetch 的测试并行。
// 本夹具约定每段最多两次完整范围请求，不模拟浏览器底层续传或真实网络。
import { strict as assert } from 'node:assert';
import { readCaptureAsset } from './readCaptureAsset';

export type Fixture = {
  name: string;
  part: 'first' | 'middle' | 'tail';
  fault: 'before_headers' | 'stream_error' | 'short_body';
  failCount: 1 | -1;
  shouldSucceed: boolean;
  minimumRequestsForPart: number;
};
type Progress = { fraction: number; available: number };
export type Outcome = {
  name: string;
  passed: boolean;
  requests: number[];
  returnedBytes: number | null;
  rejected: boolean;
  error: string | null;
  failureSignal: string | null;
};
const TOTAL = 5242917;
const PREFIX = 293625;
const STARTS = [0, 2097152, 4194304] as const;
const ENDS = [2097151, 4194303, 5242916] as const;
const LENGTHS = [2097152, 2097152, 1048613] as const;
const INDEX = { first: 0, middle: 1, tail: 2 } as const;
const text = (e: unknown): string => e instanceof Error ? e.message : String(e);

export async function runFixtures(fixtures: readonly Fixture[]): Promise<Outcome[]> {
  const expected = new Uint8Array(TOTAL);
  for (let i = 0; i < TOTAL; i++) {
    expected[i] = (Math.imul(i ^ (i >>> 11), 31) + (i >>> 17)) & 255;
  }
  const outcomes: Outcome[] = [];
  for (const fixture of fixtures) {
    assert.ok(fixture.failCount === 1 || fixture.failCount === -1);
    assert.equal(fixture.shouldSucceed, fixture.failCount === 1);
    assert.equal(fixture.minimumRequestsForPart, 2);
    const target = INDEX[fixture.part];
    const counts = [0, 0, 0];
    const complete = new Set<number>();
    const active = new Set<ReadableStreamDefaultController<Uint8Array>>();
    const progress: Progress[] = [];
    const protocolErrors: string[] = [];
    const savedFetch = globalThis.fetch;
    const abort = new AbortController();
    let result: ArrayBuffer | undefined;
    let rejected = false;
    let caught: unknown;
    let failureSignal: string | null = null;

    const fake: typeof fetch = async (input, init) => {
      try {
        if (init?.signal?.aborted) throw new Error('fixture aborted');
        const address = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
        const url = new URL(address);
        assert.equal(url.origin, 'https://fixture.invalid');
        assert.equal(url.pathname, '/grass.glb');
        assert.equal(init?.method ?? 'GET', 'GET');
        const partText = url.searchParams.get('part');
        assert.notEqual(partText, null, '必须使用完整分段请求，不允许回退到真实下载');
        const index = STARTS.findIndex(start => String(start) === partText);
        assert.ok(index >= 0, '未知分段或尝试续传后缀');
        const headers = new Headers(init?.headers ?? (input instanceof Request ? input.headers : undefined));
        assert.equal(headers.get('Range'), `bytes=${STARTS[index]}-${ENDS[index]}`);
        counts[index]++;
        assert.ok(counts[index] <= 2, '超出每段两次请求上限');
        const broken = index === target && (fixture.failCount === -1 || counts[index] <= fixture.failCount);
        if (broken && fixture.fault === 'before_headers') {
          throw new TypeError('fixture before_headers');
        }
        const start = STARTS[index];
        const length = LENGTHS[index];
        let stage = 0;
        const body = new ReadableStream<Uint8Array>({
          start(controller) { active.add(controller); },
          pull(controller) {
            if (!broken) {
              controller.enqueue(expected.slice(start, start + length));
              complete.add(index);
              active.delete(controller);
              controller.close();
              return;
            }
            if (stage++ === 0) {
              controller.enqueue(expected.slice(start, start + PREFIX));
              return;
            }
            active.delete(controller);
            if (fixture.fault === 'stream_error') {
              controller.error(new TypeError('fixture stream_error after 293625 bytes'));
            } else {
              controller.close();
            }
          },
          cancel() {
            // 被测实现可以取消响应；最终清理会清除此控制器。
          }
        }, { highWaterMark: 0 });
        // highWaterMark=0 禁止预取：读取者先取得前缀，下次读取才失败或正常结束。
        // short_body 保留宣告的完整长度和范围，但实际只返回 PREFIX 字节。
        return new Response(body, {
          status: 206,
          headers: {
            'Content-Range': `bytes ${start}-${ENDS[index]}/${TOTAL}`,
            'Content-Length': String(length),
            'Content-Type': 'application/octet-stream'
          }
        });
      } catch (e) {
        if (!(e instanceof TypeError && e.message === 'fixture before_headers')) {
          protocolErrors.push(text(e));
        }
        throw e;
      }
    };

    globalThis.fetch = fake;
    try {
      try {
        result = await readCaptureAsset('https://fixture.invalid/grass.glb', abort.signal, fraction => {
          progress.push({
            fraction,
            available: [...complete].reduce((sum, index) => sum + LENGTHS[index], 0)
          });
        });
      } catch (e) {
        rejected = true;
        caught = e;
      }
      // 仅排空本地 Promise；无计时器、随机抖动或墙钟门限。
      for (let i = 0; i < 32; i++) await Promise.resolve();
      try {
        assert.deepEqual(protocolErrors, [], '离线请求协议或预算违规');
        assert.equal(rejected, !fixture.shouldSucceed, `整文件结果错误：${text(caught)}`);
        assert.ok(counts[target] >= fixture.minimumRequestsForPart, '失败段尝试不足');
        assert.ok(counts.every(count => count <= 2), '失败后没有有限终止');
        const allowed = new Set([0, 2097152, 3145765, 4194304, TOTAL]);
        let committed = 0;
        for (const event of progress) {
          assert.ok(Number.isFinite(event.fraction), '进度必须有限');
          const scaled = event.fraction * TOTAL;
          const bytes = Math.round(scaled);
          assert.ok(Math.abs(scaled - bytes) < 0.000001, '进度不对应整数字节');
          assert.ok(allowed.has(bytes), '部分故障前缀被计作已提交数据');
          assert.ok(bytes >= committed, '已提交进度倒退');
          assert.ok(bytes <= event.available, '完整有效分段尚未收齐就提交');
          const delta = bytes - committed;
          assert.ok(delta === 0 || delta === 2097152 || delta === 1048613, '非完整分段提交或重复计数');
          committed = bytes;
        }
        if (fixture.shouldSucceed) {
          assert.ok(result instanceof ArrayBuffer, '必须返回整文件 ArrayBuffer');
          assert.equal(result.byteLength, TOTAL);
          assert.deepEqual(new Uint8Array(result), expected, '恢复结果有错位、重复、缺失或字节污染');
          assert.equal(committed, TOTAL, '成功后已提交进度未达到整文件');
        } else {
          assert.equal(result, undefined, '持续故障不得返回部分文件');
          assert.ok(committed < TOTAL, '持续故障不得报告完成');
        }
      } catch (e) {
        failureSignal = text(e);
      }
    } finally {
      abort.abort();
      for (const controller of active) {
        try { controller.error(new Error('fixture cleanup')); } catch {}
      }
      active.clear();
      for (let i = 0; i < 32; i++) await Promise.resolve();
      globalThis.fetch = savedFetch;
    }
    outcomes.push({
      name: fixture.name,
      passed: failureSignal === null,
      requests: [...counts],
      returnedBytes: result?.byteLength ?? null,
      rejected,
      error: rejected ? text(caught) : null,
      failureSignal
    });
  }
  return outcomes;
}

export function assertPassing(outcomes: readonly Outcome[]): void {
  assert.deepEqual(outcomes.filter(outcome => !outcome.passed), [], '分段恢复回归失败；查看各项请求次数和 failureSignal');
}
",
    "failureSignal": "额外诊断选用 middle_stream_error_once：完整首段后，中段读取者取得 293625 字节，下一次读取收到注入的 TypeError。正确行为是丢弃该前缀、对 bytes=2097152-4194303 再请求一次，然后返回精确 5242917 字节，且进度不出现部分前缀提交。发布源码预计直接拒绝，目标段 requests[1] 为 1，因此触发“整文件结果错误”或“失败段尝试不足”。若修复后仍将部分数据计入提交，则进度断言或最终逐字节比较失败。持续故障例则必须拒绝且 requests[1] 为 2；只拒绝一次并不满足该恢复合同。以上均为拟新增诊断及静态预期，不是已执行报告。"
  }
}

integration.operation:
// 拟新增的离线 TypeScript 诊断文件；从同目录导入被测实现。
// 本地 TS 测试运行器调用 runFixtures(本响应.fixtures)，再调用 assertPassing(结果)。
// 全程替换 fetch，不调用保存的原 fetch；禁止与其他修改全局 fetch 的测试并行。
// 本夹具约定每段最多两次完整范围请求，不模拟浏览器底层续传或真实网络。
import { strict as assert } from 'node:assert';
import { readCaptureAsset } from './readCaptureAsset';

export type Fixture = {
  name: string;
  part: 'first' | 'middle' | 'tail';
  fault: 'before_headers' | 'stream_error' | 'short_body';
  failCount: 1 | -1;
  shouldSucceed: boolean;
  minimumRequestsForPart: number;
};
type Progress = { fraction: number; available: number };
export type Outcome = {
  name: string;
  passed: boolean;
  requests: number[];
  returnedBytes: number | null;
  rejected: boolean;
  error: string | null;
  failureSignal: string | null;
};
const TOTAL = 5242917;
const PREFIX = 293625;
const STARTS = [0, 2097152, 4194304] as const;
const ENDS = [2097151, 4194303, 5242916] as const;
const LENGTHS = [2097152, 2097152, 1048613] as const;
const INDEX = { first: 0, middle: 1, tail: 2 } as const;
const text = (e: unknown): string => e instanceof Error ? e.message : String(e);

export async function runFixtures(fixtures: readonly Fixture[]): Promise<Outcome[]> {
  const expected = new Uint8Array(TOTAL);
  for (let i = 0; i < TOTAL; i++) {
    expected[i] = (Math.imul(i ^ (i >>> 11), 31) + (i >>> 17)) & 255;
  }
  const outcomes: Outcome[] = [];
  for (const fixture of fixtures) {
    assert.ok(fixture.failCount === 1 || fixture.failCount === -1);
    assert.equal(fixture.shouldSucceed, fixture.failCount === 1);
    assert.equal(fixture.minimumRequestsForPart, 2);
    const target = INDEX[fixture.part];
    const counts = [0, 0, 0];
    const complete = new Set<number>();
    const active = new Set<ReadableStreamDefaultController<Uint8Array>>();
    const progress: Progress[] = [];
    const protocolErrors: string[] = [];
    const savedFetch = globalThis.fetch;
    const abort = new AbortController();
    let result: ArrayBuffer | undefined;
    let rejected = false;
    let caught: unknown;
    let failureSignal: string | null = null;

    const fake: typeof fetch = async (input, init) => {
      try {
        if (init?.signal?.aborted) throw new Error('fixture aborted');
        const address = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
        const url = new URL(address);
        assert.equal(url.origin, 'https://fixture.invalid');
        assert.equal(url.pathname, '/grass.glb');
        assert.equal(init?.method ?? 'GET', 'GET');
        const partText = url.searchParams.get('part');
        assert.notEqual(partText, null, '必须使用完整分段请求，不允许回退到真实下载');
        const index = STARTS.findIndex(start => String(start) === partText);
        assert.ok(index >= 0, '未知分段或尝试续传后缀');
        const headers = new Headers(init?.headers ?? (input instanceof Request ? input.headers : undefined));
        assert.equal(headers.get('Range'), `bytes=${STARTS[index]}-${ENDS[index]}`);
        counts[index]++;
        assert.ok(counts[index] <= 2, '超出每段两次请求上限');
        const broken = index === target && (fixture.failCount === -1 || counts[index] <= fixture.failCount);
        if (broken && fixture.fault === 'before_headers') {
          throw new TypeError('fixture before_headers');
        }
        const start = STARTS[index];
        const length = LENGTHS[index];
        let stage = 0;
        const body = new ReadableStream<Uint8Array>({
          start(controller) { active.add(controller); },
          pull(controller) {
            if (!broken) {
              controller.enqueue(expected.slice(start, start + length));
              complete.add(index);
              active.delete(controller);
              controller.close();
              return;
            }
            if (stage++ === 0) {
              controller.enqueue(expected.slice(start, start + PREFIX));
              return;
            }
            active.delete(controller);
            if (fixture.fault === 'stream_error') {
              controller.error(new TypeError('fixture stream_error after 293625 bytes'));
            } else {
              controller.close();
            }
          },
          cancel() {
            // 被测实现可以取消响应；最终清理会清除此控制器。
          }
        }, { highWaterMark: 0 });
        // highWaterMark=0 禁止预取：读取者先取得前缀，下次读取才失败或正常结束。
        // short_body 保留宣告的完整长度和范围，但实际只返回 PREFIX 字节。
        return new Response(body, {
          status: 206,
          headers: {
            'Content-Range': `bytes ${start}-${ENDS[index]}/${TOTAL}`,
            'Content-Length': String(length),
            'Content-Type': 'application/octet-stream'
          }
        });
      } catch (e) {
        if (!(e instanceof TypeError && e.message === 'fixture before_headers')) {
          protocolErrors.push(text(e));
        }
        throw e;
      }
    };

    globalThis.fetch = fake;
    try {
      try {
        result = await readCaptureAsset('https://fixture.invalid/grass.glb', abort.signal, fraction => {
          progress.push({
            fraction,
            available: [...complete].reduce((sum, index) => sum + LENGTHS[index], 0)
          });
        });
      } catch (e) {
        rejected = true;
        caught = e;
      }
      // 仅排空本地 Promise；无计时器、随机抖动或墙钟门限。
      for (let i = 0; i < 32; i++) await Promise.resolve();
      try {
        assert.deepEqual(protocolErrors, [], '离线请求协议或预算违规');
        assert.equal(rejected, !fixture.shouldSucceed, `整文件结果错误：${text(caught)}`);
        assert.ok(counts[target] >= fixture.minimumRequestsForPart, '失败段尝试不足');
        assert.ok(counts.every(count => count <= 2), '失败后没有有限终止');
        const allowed = new Set([0, 2097152, 3145765, 4194304, TOTAL]);
        let committed = 0;
        for (const event of progress) {
          assert.ok(Number.isFinite(event.fraction), '进度必须有限');
          const scaled = event.fraction * TOTAL;
          const bytes = Math.round(scaled);
          assert.ok(Math.abs(scaled - bytes) < 0.000001, '进度不对应整数字节');
          assert.ok(allowed.has(bytes), '部分故障前缀被计作已提交数据');
          assert.ok(bytes >= committed, '已提交进度倒退');
          assert.ok(bytes <= event.available, '完整有效分段尚未收齐就提交');
          const delta = bytes - committed;
          assert.ok(delta === 0 || delta === 2097152 || delta === 1048613, '非完整分段提交或重复计数');
          committed = bytes;
        }
        if (fixture.shouldSucceed) {
          assert.ok(result instanceof ArrayBuffer, '必须返回整文件 ArrayBuffer');
          assert.equal(result.byteLength, TOTAL);
          assert.deepEqual(new Uint8Array(result), expected, '恢复结果有错位、重复、缺失或字节污染');
          assert.equal(committed, TOTAL, '成功后已提交进度未达到整文件');
        } else {
          assert.equal(result, undefined, '持续故障不得返回部分文件');
          assert.ok(committed < TOTAL, '持续故障不得报告完成');
        }
      } catch (e) {
        failureSignal = text(e);
      }
    } finally {
      abort.abort();
      for (const controller of active) {
        try { controller.error(new Error('fixture cleanup')); } catch {}
      }
      active.clear();
      for (let i = 0; i < 32; i++) await Promise.resolve();
      globalThis.fetch = savedFetch;
    }
    outcomes.push({
      name: fixture.name,
      passed: failureSignal === null,
      requests: [...counts],
      returnedBytes: result?.byteLength ?? null,
      rejected,
      error: rejected ? text(caught) : null,
      failureSignal
    });
  }
  return outcomes;
}

export function assertPassing(outcomes: readonly Outcome[]): void {
  assert.deepEqual(outcomes.filter(outcome => !outcome.passed), [], '分段恢复回归失败；查看各项请求次数和 failureSignal');
}

建议将以下 TypeScript 保存为离线回归文件，由现有本地测试入口传入本响应的 fixtures 并调用 runRegression；不联网、不读取凭据。新增诊断检查中断段缺口和重试区间去重覆盖，并单独保留三条轨迹的结论。代码：

type Method = 'GET' | 'POST' | 'none';
type Target = 'public_glb' | 'gateway_inference' | 'login' | 'page' | 'unknown';
type Classification = 'web_asset' | 'model_call' | 'unverified';
type Fixture = {
  name: string;
  method: Method;
  target: Target;
  networkEvent: boolean;
  verifiedModel: boolean;
  verifiedTokenPair: boolean;
  verifiedUpstreamCredential: boolean;
  http: number;
  expected: Classification;
};
type Span = { start: number; length: number };

export function classify(f: Fixture): Classification {
  if (f.method === 'GET' && f.target === 'public_glb' && f.networkEvent) return 'web_asset';
  if (f.target === 'gateway_inference' && f.networkEvent && f.verifiedModel && f.verifiedTokenPair && f.verifiedUpstreamCredential) return 'model_call';
  return 'unverified';
}

function assert(ok: boolean, signal: string): asserts ok {
  if (!ok) throw new Error(signal);
}

function coveredBytes(spans: readonly Span[], total: number): number {
  const sorted = [...spans].sort((a, b) => a.start - b.start);
  let end = 0;
  let covered = 0;
  for (const s of sorted) {
    assert(Number.isInteger(s.start) && Number.isInteger(s.length) && s.start >= 0 && s.length > 0 && s.start + s.length <= total, 'INVALID_ASSEMBLED_SPAN');
    const next = s.start + s.length;
    covered += Math.max(0, next - Math.max(end, s.start));
    end = Math.max(end, next);
  }
  return covered;
}

export function runRegression(payload: { fixtures: readonly Fixture[] }): void {
  const fs = payload.fixtures;
  assert(fs.length >= 4 && fs.length <= 10, 'INVALID_FIXTURE_COUNT');
  assert(new Set(fs.map(f => f.name)).size === fs.length, 'DUPLICATE_FIXTURE_NAME');
  for (const f of fs) {
    assert(/^[a-z][a-z0-9_]*$/.test(f.name), 'INVALID_FIXTURE_NAME');
    assert(classify(f) === f.expected, 'RECEIPT_CLASSIFICATION_MISMATCH:' + f.name);
  }
  const asset = fs.find(f => f.name === 'failed_initial_glb_response');
  assert(asset !== undefined, 'MISSING_FAILED_TRACE_FIXTURE');
  assert(classify({ ...asset, http: 0 }) === 'web_asset', 'GLB_NETWORK_ERROR_MISCLASSIFIED');
  assert(classify({ ...asset, http: 0, networkEvent: false }) === 'unverified', 'GLB_WITHOUT_NETWORK_EVIDENCE_ACCEPTED');
  assert(classify({ ...asset, method: 'POST' }) === 'unverified', 'NON_GET_ASSET_ACCEPTED');
  const gateway = fs.find(f => f.name === 'synthetic_verified_gateway_receipt');
  assert(gateway !== undefined, 'MISSING_GATEWAY_FIXTURE');
  assert(classify({ ...gateway, networkEvent: false }) === 'unverified', 'GATEWAY_WITHOUT_RECEIPT_ACCEPTED');

  const total = 29902848;
  const size = 2097152;
  const full: Span[] = Array.from({ length: Math.ceil(total / size) }, (_, i) => ({ start: i * size, length: Math.min(size, total - i * size) }));
  const failed = full.map((s, i) => i === 8 ? { start: s.start, length: 293625 } : { ...s });
  const retry = full.map((s, i) => i === 8 ? { start: s.start + 293625, length: 1803527 } : { ...s });
  assert(293625 + 1803527 === size, 'RESUME_FRAGMENT_LENGTH_MISMATCH');
  assert(total - coveredBytes(failed, total) === 1803527, 'FAILED_TRACE_GAP_MISMATCH');
  assert(coveredBytes([...failed, ...retry], total) === total, 'RECOVERED_TRACE_COVERAGE_MISMATCH');
  assert(coveredBytes(full, total) === total, 'DIRECT_TRACE_COVERAGE_MISMATCH');
  assert(coveredBytes([...full, ...full], total) === total, 'DUPLICATE_BYTES_COUNTED_AS_NEW_COVERAGE');
}

发布检查应同时保留首次失败、恢复成功、独立直跑成功三个状态；离线夹具通过仅证明分类及覆盖诊断无回归，不自动宣布线上可靠性通过。若后续提供本地 GLB 和原始回执，再分别校验文件哈希、请求关联与渲染状态，不以合成正例替代实证。

建议新增此文件，导出以下离线 TypeScript 检查函数；由本地测试调用 runRegression(report.fixtures, recoveredPosePair)。第二个参数只能来自已有本地渲染快照，不请求网络、不自动重拍。缺少快照时明确报告固定机位前提未验证，不把 selected=13 当作矩阵证据。代码：

type Fixture = Readonly<{
  name: string;
  b1: number; b2: number;
  w1: number; w2: number;
  tip1: number; tip2: number;
  samePose: boolean;
  expected: boolean;
}>;
type CameraSnapshot = Readonly<{
  matrixWorld: readonly number[];
  projectionMatrix: readonly number[];
  viewport: readonly [number, number, number, number];
}>;
type PosePair = Readonly<{
  rest: CameraSnapshot;
  gust: CameraSnapshot;
}>;

export function purposefulGust(c: Fixture): boolean {
  return c.w2 > c.w1 && c.tip2 > c.tip1 &&
    c.b1 > 0 && c.b2 > 0 && (!c.samePose || c.b1 === c.b2);
}

function requireCondition(ok: boolean, message: string): asserts ok {
  if (!ok) throw new Error(message);
}

export function runRegression(
  cases: readonly Fixture[],
  recoveredPosePair?: PosePair
): void {
  requireCondition(cases.length >= 4 && cases.length <= 10, 'FIXTURE_COUNT');
  for (const c of cases) {
    requireCondition(/^[a-z][a-z0-9_]*$/.test(c.name), 'CASE_NAME');
    requireCondition(Number.isInteger(c.b1) && Number.isInteger(c.b2), 'COUNT_TYPE:' + c.name);
    requireCondition([c.b1, c.b2, c.w1, c.w2, c.tip1, c.tip2].every(Number.isFinite), 'NONFINITE:' + c.name);
    requireCondition(typeof c.samePose === 'boolean' && typeof c.expected === 'boolean', 'BOOLEAN_TYPE:' + c.name);
    requireCondition(purposefulGust(c) === c.expected, 'PREDICATE_MISMATCH:' + c.name);
  }
  requireCondition(recoveredPosePair !== undefined, 'FIXED_POSE_UNVERIFIED');
  const { rest, gust } = recoveredPosePair;
  for (const s of [rest, gust]) {
    requireCondition(s.matrixWorld.length === 16 && s.projectionMatrix.length === 16 && s.viewport.length === 4, 'CAMERA_SHAPE');
    requireCondition([...s.matrixWorld, ...s.projectionMatrix, ...s.viewport].every(Number.isFinite), 'CAMERA_NONFINITE');
  }
  const equal = (a: readonly number[], b: readonly number[]) =>
    a.length === b.length && a.every((v, i) => v === b[i]);
  requireCondition(
    equal(rest.matrixWorld, gust.matrixWorld) &&
    equal(rest.projectionMatrix, gust.projectionMatrix) &&
    equal(rest.viewport, gust.viewport),
    'FIXED_POSE_MISMATCH'
  );
}
